curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for user in data['members']:
        if user.get('deleted'):
            continue
        name = user.get('real_name', '') or user.get('profile', {}).get('display_name', '')
        if 'priya' in name.lower() or 'leo' in name.lower() or 'sharma' in name.lower() or 'park' in name.lower():
            print(f\"ID: {user['id']} | Name: {name}\")
else:
    print('Error:', data)
"

curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"types": "private_channel", "exclude_archived": true}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        print(f\"ID: {ch['id']} | Name: {ch['name']} | Is Private: {ch.get('is_private')}\")
else:
    print('Error:', data)
"
